import React from "react";

/**
 * Props:
 * - year: number (ex: 2023)
 * - month: number 1..12 (ex: 2 -> Février)
 * - selectedDay?: number (ex: 20)
 * - title?: string
 * - birthdayLabel?: string
 */
export default function PrettyCalendar({
    year = 2023,
    month = 2,
    selectedDay = 20,
    title = "Un jour spécial pour ?",
    birthdayLabel = "Anniversaire de Ousmane DIA",
}) {
    const monthIndex = month - 1;
    const monthName = new Date(year, monthIndex, 1).toLocaleString("en-US", { month: "long" });
    const firstWeekday = new Date(year, monthIndex, 1).getDay(); // 0=Sun..6=Sat
    const daysInMonth = new Date(year, month, 0).getDate();

    const cells = [
        ...Array(firstWeekday).fill(null),
        ...Array.from({ length: daysInMonth }, (_, i) => i + 1),
    ];
    while (cells.length % 7 !== 0) cells.push(null);

    const weekLabels = ["SUN", "MON", "TUE", "WED", "THU", "FRI", "SAT"];

    return (
        <div>
            {/* Titre */}
            <h3 className="text-[#1c2b68] font-semibold text-2xl mb-3">{title}</h3>

            {/* Carte calendrier */}
            <div className="bg-white rounded-2xl shadow-md p-5">
                <div className="text-center">
                    <div className="uppercase tracking-wide text-2xl md:text-3xl text-blueGray-600">
                        {monthName.toUpperCase()} {year}
                    </div>
                </div>

                {/* Bandeau jours en pilule */}
                <div className="mt-4 bg-blueGray-100 rounded-full px-3 py-2">
                    <div className="grid grid-cols-7 text-center text-xs md:text-[13px] font-semibold">
                        {weekLabels.map((w, i) => (
                            <div
                                key={w}
                                className={`py-1 ${i === 0 ? "text-red-500" : "text-blueGray-500"}`}
                            >
                                {w}
                            </div>
                        ))}
                    </div>
                </div>

                {/* Grille dates */}
                <div className="mt-4 grid grid-cols-7 gap-y-4">
                    {cells.map((v, idx) => {
                        const col = idx % 7;
                        const isSunday = col === 0;
                        const isSelected = v === selectedDay && v !== null;

                        return (
                            <div key={idx} className="h-8 flex items-center justify-center">
                                {v === null ? (
                                    <span className="text-blueGray-300 select-none"> </span>
                                ) : (
                                    <div
                                        className={`w-10 h-10 flex items-center justify-center ${isSelected ? "bg-[#e8b6b6] rounded-md" : ""
                                            }`}
                                    >
                                        <span
                                            className={`text-[15px] ${isSunday
                                                    ? (isSelected ? "text-[#6b1410]" : "text-red-500")
                                                    : (isSelected ? "text-[#6b1410]" : "text-blueGray-600")
                                                }`}
                                        >
                                            {v}
                                        </span>
                                    </div>
                                )}
                            </div>
                        );
                    })}
                </div>
            </div>

            {/* Légende anniversaire */}
            <div className="mt-5 flex items-center justify-between">
                <span className="text-blueGray-800 font-semibold text-lg md:text-xl">
                    {birthdayLabel}
                </span>
                <span role="img" aria-label="party" className="text-2xl md:text-3xl">🎉</span>
            </div>
        </div>
    );
}
